package br.com.admeclesial.interfaces.web.relatorio;
import br.com.admeclesial.application.relatorio.*; import br.com.admeclesial.domain.projeto.*; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.UUID;
@Controller @RequestMapping("/relatorios/projetos-obras") public class RelatorioProjetoWebController { final RelatorioProjetoApplicationService service; final RelatorioContextoService contexto; public RelatorioProjetoWebController(RelatorioProjetoApplicationService s,RelatorioContextoService c){service=s;contexto=c;}
 @GetMapping public String tela(@RequestParam(required=false) UUID organizacaoUuid,@RequestParam(required=false) TipoProjeto tipo,@RequestParam(required=false) StatusProjeto status,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate inicio,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate fim,@RequestParam(defaultValue="false") boolean somenteRecursoSemUtilizacao,@RequestParam(defaultValue="0") int pagina,@RequestParam(defaultValue="25") int tamanho,Model m){m.addAttribute("organizacoes",contexto.organizacoesAutorizadas());m.addAttribute("tipos",TipoProjeto.values());m.addAttribute("statusOpcoes",StatusProjeto.values());m.addAttribute("organizacaoUuid",organizacaoUuid);m.addAttribute("tipo",tipo);m.addAttribute("status",status);m.addAttribute("inicio",inicio);m.addAttribute("fim",fim);m.addAttribute("somenteRecursoSemUtilizacao",somenteRecursoSemUtilizacao);if(organizacaoUuid!=null){var f=new RelatorioProjetoFiltro(organizacaoUuid,tipo,status,inicio,fim,somenteRecursoSemUtilizacao,pagina,tamanho);m.addAttribute("resultado",service.pesquisar(f));m.addAttribute("resumo",service.resumo(f));}return "relatorio/projetos-obras";}
}
